<?php

namespace App\Support;

/**
 * The avatar roster: collections of looks × 7 skin shades.
 *   retro  — 16 pixel-art 90s characters (ids f1…, m1…)
 *   heroes — 12 original comic-style heroes (ids h1…)
 *   genz   — 12 original streetwear characters (ids g1…)
 *   illus  — 12 DiceBear Lorelei illustrations, CC0 (ids i1…)
 * An avatar key is "{look}-{skin}", e.g. "f3-4" or "h7-2". Files live in public/avatars/
 * (generated by scripts/build-avatars.mjs, which also writes resources/avatars.json).
 */
class Avatars
{
    public static function roster(): array
    {
        static $r = null;

        return $r ??= json_decode(file_get_contents(resource_path('avatars.json')), true);
    }

    public static function collections(): array
    {
        return self::roster()['collections'];
    }

    /** Every look across every collection. */
    public static function looks(): array
    {
        return array_merge(...array_column(self::collections(), 'looks'));
    }

    public static function skins(): array
    {
        return self::roster()['skins'];
    }

    public static function valid(?string $key): bool
    {
        if (!$key || !preg_match('/^([a-z]\d+)-(\d+)$/', $key, $m)) {
            return false;
        }

        return in_array($m[1], array_column(self::looks(), 'id'), true)
            && in_array((int) $m[2], array_column(self::skins(), 'id'), true);
    }

    /** A varied default for seat $order — alternates women/men from the retro set and walks through the skin shades. */
    public static function default(int $order): string
    {
        $retro = self::collections()[0]['looks'];
        $women = array_values(array_filter($retro, fn ($l) => $l['gender'] === 'f'));
        $men = array_values(array_filter($retro, fn ($l) => $l['gender'] === 'm'));
        $pool = $order % 2 === 0 ? $men : $women;
        $look = $pool[intdiv($order, 2) % count($pool)]['id'];
        $skins = self::skins();

        return $look . '-' . $skins[($order * 3 + 1) % count($skins)]['id'];
    }

    public static function url(string $key): string
    {
        return asset("avatars/{$key}.svg");
    }
}
